 const r={xmin:cx-w*factor/2,xmax:cx+w*factor/2,ymin:cy-h*factor/2,ymax:cy+h*factor/2};
 if(w*factor<Math.max(Math.abs(cx)*1e-12,1e-12)||h*factor<Math.max(Math.abs(cy)*1e-12,1e-12))return {...range};
