const SMART_PAIRS={pt:['p','T'],ph:['p','h'],ps:['p','s'],pv:['p','v'],pu:['p','u'],th:['T','h'],ts:['T','s'],tv:['T','v'],tu:['T','u'],hs:['h','s'],us:['u','s'],vs:['v','s'],hv:['h','v'],uv:['u','v'],satp:['p','sat'],satt:['T','sat'],px:['p','x'],tx:['T','x'],prho:['p','rho'],trho:['T','rho']};
