const NPP_REFERENCE={url:'https://aris.iaea.org/Characteristics/',design:'VVER-1000 (V-466B)',accessed:'2026-10-11',thermalMW:3000,primaryP:15.7,coldC:291,hotC:321,steamP:6.27};
