// src/cycle-study.js
const CYCLE_DEFAULT={type:'rankine',pLow:.01,pHigh:10,pMid:2,Tmin:300,Tmax:773.15,Tmid:773.15,etaT:.85,etaC:.8,flow:1};
function solveCycle(input=CYCLE_DEFAULT,model='IF97'){
 const a={...CYCLE_DEFAULT,...input};if(!['rankine','rankine-reheat','rankine-regen','brayton'].includes(a.type))throw Error('Невідомий тип циклу.');
 const q=a.type==='brayton'?brayton(a.pLow,a.pHigh,a.Tmin,a.Tmax,a.etaT,a.etaC,a.flow):a.type==='rankine-reheat'?rankineReheat(a.pHigh,a.pMid,a.pLow,a.Tmax,a.Tmid,a.etaT,a.etaC,a.flow,model):a.type==='rankine-regen'?rankineRegen(a.pHigh,a.pMid,a.pLow,a.Tmax,a.etaT,a.etaC,a.flow,model):rankine(a.pHigh,a.pLow,a.Tmax,a.etaT,a.etaC,a.flow,model);
 const names=a.type==='rankine-regen'?['T1','E1','T2','C1','P1','F1','P2']:q.states.map((_,i)=>'S'+(i+1));
 const edges=a.type==='rankine-regen'?[[0,1],[1,2],[2,3],[3,4],[4,5],[1,5],[5,6],[6,0]]:q.states.map((_,i)=>[i,(i+1)%q.states.length]);
 return {...q,input:a,states:q.states.map((s,i)=>({...s,name:names[i]})),edges,balanceResidual:q.heat-q.rejected-q.net,extractionFraction:a.type==='rankine-regen'?(q.states[5].h-q.states[4].h)/(q.states[1].h-q.states[4].h):null};
}


// src/exchanger-design.js
const EXCHANGER_DEFAULT={arrangement:'counter',hotIn:423.15,hotOut:373.15,coldIn:293.15,coldOut:343.15,heatKW:100,U:500};
function exchangerDesign(input=EXCHANGER_DEFAULT){
 const a={...EXCHANGER_DEFAULT,...input};if(!['counter','parallel'].includes(a.arrangement)||!['hotIn','hotOut','coldIn','coldOut','heatKW','U'].every(k=>Number.isFinite(a[k]))||Math.min(a.hotIn,a.hotOut,a.coldIn,a.coldOut)<=0||a.heatKW<=0||a.U<=0||a.hotOut>=a.hotIn||a.coldOut<=a.coldIn)throw Error('Теплообмінник: перевірте температури, Q > 0 та U > 0.');
 const delta1=a.hotIn-(a.arrangement==='counter'?a.coldOut:a.coldIn),delta2=a.hotOut-(a.arrangement==='counter'?a.coldIn:a.coldOut);
 if(delta1<=0||delta2<=0)throw Error('Перетин температур або нульовий напір: скінченна площа неможлива.');
 const ratio=(delta1-delta2)/delta2,lmtd=Math.abs(ratio)<1e-10?(delta1+delta2)/2:(delta1-delta2)/Math.log1p(ratio),UA=a.heatKW*1000/lmtd,area=UA/a.U;
 return {input:a,model:'LMTD',states:[],delta1,delta2,lmtd,UA,area,heatKW:a.heatKW,U:a.U,assumptions:['Q = U A ΔTlm; ΔTlm = (ΔT₁−ΔT₂)/ln(ΔT₁/ΔT₂).','Ідеальна прямотечія або протитечія, F = 1, сталий U і сталі теплоємності потоків. Температури кінців задані; внутрішній профіль не розраховується.','U задається користувачем; геометрія, забруднення та кореляції тепловіддачі не визначаються.']};
}


// src/research.js
const RESEARCH_PARAMETERS={cycles:['pLow','pHigh','pMid','Tmin','Tmax','Tmid','etaT','etaC','flow'],npp:['thermalMW','primaryP','coldC','hotC','steamP','condenserP','etaT','etaPump','pMid','reheatC','etaLP'],exchanger:['hotIn','hotOut','coldIn','coldOut','heatKW','U']};
function solveStudyModule(module,input,model='IF97'){
 if(!['IF97','IAPWS-95'].includes(model))throw Error('Невідома модель дослідження.');
 if(module==='cycles')return solveCycle(input,model);if(module==='npp')return solveNuclear(input,model);if(module==='exchanger')return exchangerDesign(input);throw Error('Невідомий модуль дослідження.');
}
function researchMetrics(module,q){return module==='exchanger'?{area:q.area,lmtd:q.lmtd}:{netKW:module==='npp'?q.netKW:q.power,efficiency:q.efficiency,outletX:module==='npp'?(q.states.find(s=>s.name===(q.mode==='msr'?'L1':'S4'))?.x??null):((q.input.type==='rankine-regen'?q.states[2]:q.states.at(-1)).x??null)};}
function validateSweep(a){
 if(!a||!RESEARCH_PARAMETERS[a.module]?.includes(a.parameter)||!Number.isFinite(a.start)||!Number.isFinite(a.end)||a.start===a.end||!Number.isInteger(a.count)||a.count<2||a.count>41)throw Error('Дослідження: оберіть параметр, різні межі й 2…41 точку.');
 const active=a.module==='npp'?(a.base?.mode==='msr'?Object.keys(NPP_MSR_DEFAULT):Object.keys(NPP_DEFAULT)):a.module==='cycles'?(a.base?.type==='brayton'?['pLow','pHigh','Tmin','Tmax','etaT','etaC','flow']:a.base?.type==='rankine-reheat'?Object.keys(CYCLE_DEFAULT):a.base?.type==='rankine-regen'?Object.keys(CYCLE_DEFAULT).filter(k=>!['Tmin','Tmid'].includes(k)):['pLow','pHigh','Tmax','etaT','etaC','flow']):Object.keys(EXCHANGER_DEFAULT);
 if(!active.includes(a.parameter))throw Error('Цей параметр не діє на обраний режим.');
 solveStudyModule(a.module,a.base,a.model);return a;
}
function sweepPoint(a,i){const value=i===a.count-1?a.end:a.start+(a.end-a.start)*i/(a.count-1);try{return {value,...researchMetrics(a.module,solveStudyModule(a.module,{...a.base,[a.parameter]:value},a.model)),error:null};}catch(e){return {value,error:e.message};}}
function researchSeries(a){validateSweep(a);return Array.from({length:a.count},(_,i)=>sweepPoint(a,i));}
function readResearch(value){
 if(value==null)return {variants:[],sweep:null};if(!value||!Array.isArray(value.variants)||value.variants.length>8||JSON.stringify(value).length>50000)throw Error('Дослідження: максимум 8 варіантів.');
 const variants=value.variants.map(v=>{if(typeof v.title!=='string'||v.title.length>120)throw Error('Некоректна назва варіанта.');const q=solveStudyModule(v.module,v.input,v.model);return {title:v.title,module:v.module,input:q.input,model:v.model||'IF97'};});
 const sweep=value.sweep?JSON.parse(JSON.stringify(validateSweep(value.sweep))):null;return {variants,sweep};
}
