 if(['p','p1','p2','uP'].includes(key)){const p=key==='uP'||a.basis==='absolute'?value:a.basis==='gauge'?value-a.atmosphere*.001:a.atmosphere*.001-value;return fromCanonical(p,a.pressure);}
