function reactorCampaignSVG(q,en=false){
 if(!q.neutronics)return '';const rows=q.neutronics.campaign.profile,values=rows.map(r=>r.keff).concat(q.input.campaignTarget),low=Math.min(...values),high=Math.max(...values),span=high-low||1,X=t=>70+660*t/q.input.campaignMaxDays,Y=k=>280-210*(k-low)/span;
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 350" role="img" aria-label="${en?'Experimental campaign k_eff':'Дослідна оцінка kеф кампанії'}"><g font-family="Arial" font-size="14"><path d="M70 60V280H740" fill="none" stroke="#666"/><text x="70" y="25">${en?'Experimental campaign k_eff':'Дослідна оцінка kеф кампанії'}</text><text x="400" y="330">t [day]</text><text x="10" y="65">${high.toPrecision(5)}</text><text x="10" y="280">${low.toPrecision(5)}</text><text x="70" y="305">0</text><text x="680" y="305">${q.input.campaignMaxDays}</text><path d="M70 ${Y(q.input.campaignTarget)}H730" fill="none" stroke="#b91c1c" stroke-dasharray="5 4"/><polyline points="${rows.map(r=>X(r.days)+','+Y(r.keff)).join(' ')}" fill="none" stroke="#125a88" stroke-width="2"/></g></svg>`;
}
function reactorReportSummary(q,en=false){
 const t=(uk,enText)=>en?enText:uk,N=v=>Number(v.toPrecision(8)),m=q.metrics,checked=reactorCalculationChecks(q);
 return `<aside><h3>${t('Статус записки: у розробці — розрахунок для перевірки','Report status: in development — calculation draft')}</h3><p>${t('Теплові властивості обчислено за обраним ядром. Нейтронна частина дослідна. CHF і поверхневе кипіння обчислюються за обраними кореляціями; резонансний інтеграл — розрахований або заданий; розташування стрижнів — за обраною схемою. Статус кожного розділу наведено окремо. Фізична застосовність наближень, квадратна гранична поправка та контрольний приклад усієї курсової ще потребують звірки.','Water properties use the selected engine. Neutronics is experimental. CHF and subcooled boiling use selected correlations; the resonance integral is calculated or specified; rod layout uses the selected method. Each section has an explicit status. Physical applicability, the square boundary correction and the full coursework reference example still need verification.')}</p><p>${t('Контроль рівнянь поточного розрахунку: ','Current equation checks: ')}${checked.status==='passed'?t('у допуску.','within tolerance.'):t('є розбіжності.','discrepancies found.')} ${t('Експериментальні нейтронні еталони моделі не пройдені. Контрольні приклади та числові допуски наведено нижче окремо від фізичної перевірки.','The model fails experimental neutron screening. Reference cases and numerical tolerances are listed below separately from physical validation.')}</p></aside><h3>${t('Мета та послідовність розрахунку','Objective and calculation sequence')}</h3><p>${t('За геометрією варіанта й електричною потужністю визначаються теплова потужність, витрата теплоносія та розміри активної зони. Для гарячого каналу розраховуються сім контрольних перетинів і докладний осьовий профіль. Температури шарів знаходяться з урахуванням їх теплопровідності. Окремий середній канал забезпечує вхідні температури для нейтронної моделі.','Variant geometry and electrical power determine thermal power, coolant flow and core dimensions. The hot channel is evaluated at seven control sections and on a detailed axial grid. Layer temperatures use their conductivities. A separate mean channel supplies temperatures for the neutron model.')}</p><h3>${t('Висновки за фактичними результатами','Conclusions from calculated values')}</h3><p>Q = ${N(m.thermalMW)} MW; G = ${N(m.flow)} kg/s; H = ${N(m.height)} m; D = ${N(m.diameter)} m.</p><p>${t('Максимальна зовнішня температура оболонки','Maximum outer cladding temperature')}: ${N(m.maxCladOuter)} °C; ${t('задана межа','specified limit')}: ${q.input.cladLimit} °C. ${t('Максимальна температура палива','Maximum fuel temperature')}: ${N(m.maxFuelCenter)} °C; ${t('задана межа','specified limit')}: ${q.input.fuelLimit} °C.</p><p>${t('Розрахований перепад тиску','Calculated pressure drop')}: ${N(m.calculatedDrop)} MPa; ${t('заданий','specified')}: ${q.input.pressureDrop} MPa. ${t('Ці перевірки стосуються заданої навчальної моделі; вони не є оцінкою безпечності реактора.','These checks apply to the specified course model; they are not a reactor safety assessment.')}</p>`;
}

function reactorCHFSVG(q,en=false){
 if(!q.chf)return '';const rows=q.chf,hi=Math.max(q.input.chfLimit,...rows.map(r=>r.ratio))*1.05,X=z=>70+660*(z/q.metrics.height+.5),Y=v=>280-220*v/hi;
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 350" role="img" aria-label="CHF/q"><g font-family="Arial" font-size="14"><text x="70" y="25">${en?'CHF/q — correlation applicability requires review':'CHF/q — застосовність кореляції потребує звірки'}</text><path d="M70 50V280H740" fill="none" stroke="#666"/><text x="5" y="65">${hi.toPrecision(4)}</text><text x="45" y="280">0</text><text x="365" y="330">z [m]</text><text x="70" y="305">${rows[0].z.toPrecision(4)}</text><text x="680" y="305">${rows.at(-1).z.toPrecision(4)}</text><path d="M70 ${Y(q.input.chfLimit)}H730" fill="none" stroke="#b91c1c" stroke-dasharray="5 4"/><polyline points="${rows.map(r=>X(r.z)+','+Y(r.ratio)).join(' ')}" fill="none" stroke="#125a88" stroke-width="2"/></g></svg>`;
}
function reactorLayoutSVG(q,en=false){
 if(!q.neutronics)return '';const rows=q.neutronics.controls.rings,R=q.metrics.diameter/2,scale=165/R,cx=235,cy=225,coordinate=q.input.rodLayout==='coordinates';
 const marks=rows.map(r=>coordinate?`<circle cx="${cx+r.x*scale}" cy="${cy-r.y*scale}" r="4" fill="#125a88"/>`:`<circle cx="${cx}" cy="${cy}" r="${r.radius*scale||3}" fill="none" stroke="#125a88"/>`).join('');
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 440" role="img" aria-label="${en?'Specified rod layout':'Задана схема стрижнів'}"><g font-family="Arial" font-size="14"><text x="60" y="25">${en?'Specified rod layout (assembly centres)':'Задана схема стрижнів (центри касет)'}</text><circle cx="${cx}" cy="${cy}" r="165" fill="none" stroke="#666"/><path d="M70 225H400M235 60V390" stroke="#ccc"/>${marks}<text x="460" y="90">R = ${R.toPrecision(6)} m</text><text x="460" y="120">${en?'Assemblies':'Касет'}: ${q.input.controlAssemblies}</text><text x="460" y="150">${en?'Rods per assembly':'ПЕЛів у касеті'}: ${q.input.rodsPerCluster}</text><text x="460" y="180">Δk = ${q.neutronics.controls.totalWorth.toPrecision(6)}</text><text x="60" y="420">${coordinate?(en?'Coordinates supplied by user':'Координати задано користувачем'):(en?'Circles show radii; angular positions are not specified':'Кола показують радіуси; кутові положення не задані')}</text></g></svg>`;
}


// src/coursework.js

// Course templates are input-only. No values from the supplied Word/Excel tables
// are used as intermediate results. Units: MPa absolute, °C, mm, MW, SI otherwise.
const COURSE_FIELDS={
 reactor:REACTOR_FIELDS,
 rankine:[['pHigh',9.5,'MPa','Тиск перед турбіною','Turbine inlet pressure'],['tHigh',500,'°C','Температура перед турбіною','Turbine inlet temperature'],['pLow',.0055,'MPa','Тиск конденсатора','Condenser pressure'],['etaT',1,'–','Ізоентропний ККД турбіни','Turbine isentropic efficiency'],['etaPump',.82,'–','ККД насоса','Pump efficiency'],['flow',1,'kg/s','Витрата пари','Steam mass flow']],
 stage:[['pIn',17.2,'MPa','Тиск перед ступенем','Stage inlet pressure'],['tIn',500,'°C','Температура перед ступенем','Stage inlet temperature'],['pOut',14.5,'MPa','Тиск після ступеня','Stage outlet pressure'],['flow',290,'kg/s','Витрата пари','Steam mass flow'],['speedRatio',.48,'–','u / cф','u / c fictitious'],['reaction',.1,'–','Ступінь реактивності','Degree of reaction'],['alpha1',13,'°','Кут α₁ до колової осі','α₁ angle to tangential axis'],['betaOffset',5,'°','β₁ − β₂','β₁ − β₂'],['phi',.97,'–','Коефіцієнт швидкості сопел φ','Nozzle velocity coefficient φ'],['psi',.935,'–','Коефіцієнт швидкості ротора ψ','Rotor velocity coefficient ψ'],['c0',50,'m/s','Швидкість на вході','Inlet velocity'],['frequency',50,'s⁻¹','Частота обертання','Rotational frequency'],['recovery',0,'–','Частка використання вихідної кінетичної енергії χ','Exit kinetic energy recovery fraction χ']],
 core:[['thermalMW',700,'MW','Теплова потужність','Thermal power'],['pIn',16,'MPa','Тиск на вході','Inlet pressure'],['pressureDrop',.1,'MPa','Перепад тиску (заданий)','Pressure drop (specified)'],['tIn',290,'°C','Температура на вході','Inlet temperature'],['tOut',320,'°C','Середня температура на виході','Mean outlet temperature'],['rodDiameter',8,'mm','Зовнішній діаметр ТВЕЛа','Fuel rod outer diameter'],['pitchRatio',1.4,'–','Крок / діаметр ТВЕЛа','Pitch / rod diameter'],['cladThickness',.5,'mm','Товщина оболонки','Cladding thickness'],['gap',.06,'mm','Радіальна ширина газового зазору','Radial gas gap'],['holeDiameter',.5,'mm','Діаметр отвору в паливі','Fuel bore diameter'],['layers',11,'–','Кількість концентричних рядів','Number of concentric rows'],['rods',312,'–','Кількість ТВЕЛів у ТВЗ','Fuel rods per assembly'],['guides',19,'–','Напрямні та центральна трубка','Guide tubes including central tube'],['guideDiameter',8,'mm','Діаметр напрямних трубок','Guide tube diameter'],['ductThickness',2,'mm','Товщина чохла ТВЗ','Assembly duct thickness'],['bundleGap',2,'mm','Зазор між ТВЗ','Interassembly gap'],['volumeHeat',107.9,'MW/m³','Питоме об’ємне тепловиділення','Volumetric heat generation'],['heightRatio',1.117,'–','Висота / діаметр активної зони','Core height / diameter'],['reflector',.1004,'m','Ефективна добавка відбивача','Effective reflector extension'],['radialPeak',1.35,'–','Радіальний коефіцієнт Kr','Radial peaking factor Kr'],['hotFactor',1.87,'–','Коефіцієнт підігріву гарячого каналу','Hot channel enthalpy rise factor'],['fuelFraction',.96,'–','Частка тепла в паливі','Fraction of heat generated in fuel'],['heatFactor',1.38,'–','Коефіцієнт тепловіддачі Kα','Film temperature rise factor Kα'],['conductionFactor',1.44,'–','Коефіцієнт перепаду в оболонці та зазорі Kλ','Cladding and gap temperature rise factor Kλ'],['gapConductivity',.323,'W/(m K)','Теплопровідність газу (задана)','Gas conductivity (specified)'],['cladConductivity',20,'W/(m K)','Стала теплопровідність оболонки','Constant cladding conductivity'],['gasPressure',2,'MPa','Початковий тиск газу','Initial gas pressure'],['gasInitialK',293,'K','Початкова температура газу','Initial gas temperature'],['points',25,'–','Кількість точок уздовж висоти','Number of axial points']]
};
const COURSE_DEFAULTS=Object.fromEntries(Object.entries(COURSE_FIELDS).map(([kind,fields])=>[kind,{kind,...Object.fromEntries(fields.map(([key,v])=>[key,v])),...(kind==='reactor'?REACTOR_DEFAULT:kind==='rankine'?{pumpMethod:'volume'}:kind==='core'?{areaMethod:'duct',cladMethod:'polynomial'}:{})}]));
const COURSE_NAMES={rankine:['Цикл Ренкіна','Rankine cycle'],stage:['Ступінь турбіни','Turbine stage'],core:['Теплогідравліка активної зони','Core thermal hydraulics'],reactor:['Курсова ЯЕР за методичкою — у розробці','Reactor coursework — instructor guide (in development)']};
function courseworkInput(value){
 if(value?.kind==='reactor')return reactorInput(value);
 if(!value||!Object.hasOwn(COURSE_FIELDS,value.kind))throw Error('Оберіть тип навчальної задачі. / Select a coursework template.');
 const a={kind:value.kind};for(const [k] of COURSE_FIELDS[a.kind]){if(typeof value[k]!=='number'||!Number.isFinite(value[k]))throw Error(`${k}: потрібне скінченне число. / A finite number is required.`);a[k]=value[k];}
 if(a.kind==='rankine'){if(!['volume','isentropic'].includes(value.pumpMethod))throw Error('Невідомий метод насоса. / Unknown pump method.');a.pumpMethod=value.pumpMethod;}
 if(a.kind==='core'){for(const [k,allowed] of [['areaMethod',['duct','course']],['cladMethod',['polynomial','constant']]]){if(!allowed.includes(value[k]))throw Error('Невідоме припущення. / Unknown assumption.');a[k]=value[k];}}
 return a;
}
function courseRequire(ok,message){if(!ok)throw Error(message);}
function coursePositive(a,keys){for(const k of keys)courseRequire(a[k]>0,`${k}: значення має бути > 0. / Value must be > 0.`);}
function courseFraction(a,keys){for(const k of keys)courseRequire(a[k]>0&&a[k]<=1,`${k}: потрібно 0 < значення ≤ 1. / Require 0 < value ≤ 1.`);}
const courseNumber=n=>Number(n.toPrecision(8)).toString();
function courseStep(key,uk,en,formula,substitution,value,unit){return {key,label:[uk,en],formula,substitution,value,unit};}
function courseNote(uk,en){return [uk,en];}
function coursework(value,model='IF97'){
 if(value?.kind==='reactor')return attachReactorNeutronics(reactorCourse(value,model));
 const a=courseworkInput(value);courseRequire(['IF97','IAPWS-95'].includes(model),'Невідома модель води. / Unknown water model.');
 const q=a.kind==='rankine'?courseRankine(a,model):a.kind==='stage'?courseStage(a,model):courseCore(a,model);
 courseRequire(Object.values(q.metrics).every(Number.isFinite)&&(!q.profile||q.profile.every(r=>Object.values(r).every(Number.isFinite))),'Результат виходить за числовий діапазон. / Result exceeds the numeric range.');return q;
}
function courseRankine(a,model){
 coursePositive(a,['pHigh','pLow','flow']);courseFraction(a,['etaT','etaPump']);courseRequire(a.pHigh>a.pLow,'Тиск перед турбіною має бути вищим. / Inlet pressure must be higher.');
 const inlet=calculate('pt',a.pHigh,a.tHigh+273.15,model).state;
 courseRequire(inlet.rho<322||inlet.T>=647.096,'Перед турбіною потрібна пара. / Steam is required at the inlet.');
 const liquid=calculate('px',a.pLow,0,model).state,ideal=calculate('ps',a.pLow,inlet.s,model).state;
 const pumpIdeal=a.pumpMethod==='volume'?liquid.v*1000*(a.pHigh-a.pLow):calculate('ps',a.pHigh,liquid.s,model).state.h-liquid.h;
 const pump=pumpIdeal/a.etaPump,feed=calculate('ph',a.pHigh,liquid.h+pump,model).state;
 const outlet=calculate('ph',a.pLow,inlet.h-a.etaT*(inlet.h-ideal.h),model).state;
 const wt=inlet.h-outlet.h,q=inlet.h-feed.h,net=wt-pump,rejected=outlet.h-liquid.h;
 courseRequire(q>0&&net>0,'Задані параметри не утворюють корисний цикл. / Inputs do not form a power cycle.');
 const metrics={pump,wt,heat:q,rejected,net,efficiency:net/q,power:a.flow*net,balanceResidual:q-rejected-net};
 const steps=[courseStep('hin','Ентальпія перед турбіною','Inlet enthalpy','h₀ = h(p₀,T₀)',`${a.pHigh}; ${a.tHigh+273.15}`,inlet.h,'kJ/kg'),courseStep('sin','Ентропія перед турбіною','Inlet entropy','s₀ = s(p₀,T₀)',`${a.pHigh}; ${a.tHigh+273.15}`,inlet.s,'kJ/(kg K)'),courseStep('hIdeal','Ізоентропний вихід','Isentropic outlet','h₁s = h(pк,s₀)',`${a.pLow}; ${courseNumber(inlet.s)}`,ideal.h,'kJ/kg'),courseStep('pump','Робота насоса','Pump work',a.pumpMethod==='volume'?'wп = 1000v′(p₀−pк)/ηп':'wп = [h(p₀,s′)−h′]/ηп',a.pumpMethod==='volume'?`1000 × ${courseNumber(liquid.v)} × (${a.pHigh} − ${a.pLow}) / ${a.etaPump}`:`${courseNumber(pumpIdeal)} / ${a.etaPump}`,pump,'kJ/kg'),courseStep('wt','Робота турбіни','Turbine work','wт = ηт(h₀−h₁s)',`${a.etaT} × (${courseNumber(inlet.h)} − ${courseNumber(ideal.h)})`,wt,'kJ/kg'),courseStep('heat','Підведена теплота','Heat input','q₁ = h₀−(h′+wп)',`${courseNumber(inlet.h)} − (${courseNumber(liquid.h)} + ${courseNumber(pump)})`,q,'kJ/kg'),courseStep('net','Корисна робота','Net work','w = wт−wп',`${courseNumber(wt)} − ${courseNumber(pump)}`,net,'kJ/kg'),courseStep('efficiency','Термічний ККД','Thermal efficiency','η = w/q₁',`${courseNumber(net)} / ${courseNumber(q)}`,metrics.efficiency,'–'),courseStep('power','Потужність циклу','Cycle power','N = ṁw',`${a.flow} × ${courseNumber(net)}`,metrics.power,'kW'),courseStep('balanceResidual','Нев’язка балансу','Balance residual','ε = q₁−q₂−w',`${courseNumber(q)} − ${courseNumber(rejected)} − ${courseNumber(net)}`,metrics.balanceResidual,'kJ/kg')];
 return {input:a,model,metrics,steps,states:[{...inlet,name:'0'},{...outlet,name:'1'},{...liquid,name:'2'},{...feed,name:'3'}],ideal,warnings:[],notes:[courseNote('Без втрат тиску й тепла, регенерації та перегріву. ККД агрегатів — задані параметри.','No pressure/heat losses, regeneration or reheat. Component efficiencies are specified inputs.'),courseNote(a.pumpMethod==='volume'?'Насос: наближення нестисливої рідини v′Δp, як у контрольній роботі.':'Насос: ізоентропний перепад за моделлю води.',a.pumpMethod==='volume'?'Pump: incompressible liquid approximation v′Δp, as in the assignment.':'Pump: isentropic enthalpy rise using the water model.')]};
}
function courseStage(a,model){
 coursePositive(a,['pIn','pOut','flow','speedRatio','frequency']);courseFraction(a,['phi','psi']);
 courseRequire(a.pIn>a.pOut&&a.reaction>=0&&a.reaction<1&&a.recovery>=0&&a.recovery<=1&&a.c0>=0&&a.alpha1>0&&a.alpha1<90,'Перевірте тиски, кути, реактивність та χ. / Check pressures, angles, reaction and χ.');
 const inlet=calculate('pt',a.pIn,a.tIn+273.15,model).state;
 courseRequire(inlet.rho<322||inlet.T>=647.096,'На вході ступеня потрібна пара. / Steam is required at stage inlet.');
 const ideal=calculate('ps',a.pOut,inlet.s,model).state,H0=inlet.h+a.c0*a.c0/2000-ideal.h;
 courseRequire(H0>0,'Наявний теплоперепад має бути додатним. / Available heat drop must be positive.');
 const Hn=(1-a.reaction)*H0,Hr=a.reaction*H0,cf=Math.sqrt(2000*H0),u=a.speedRatio*cf,c1t=Math.sqrt(2000*Hn),c1=a.phi*c1t,rad=Math.PI/180;
 const c1u=c1*Math.cos(a.alpha1*rad),c1a=c1*Math.sin(a.alpha1*rad),w1u=c1u-u,w1a=c1a,w1=Math.hypot(w1u,w1a),beta1=Math.atan2(w1a,w1u)/rad,beta2=beta1-a.betaOffset;
 courseRequire(beta2>0&&beta2<90,'Потрібно 0 < β₂ < 90°. Змініть кути або u/cф. / Require 0 < β₂ < 90°; adjust angles or speed ratio.');
 const w2t=Math.sqrt(w1*w1+2000*Hr),w2=a.psi*w2t,w2u=-w2*Math.cos(beta2*rad),w2a=w2*Math.sin(beta2*rad),c2u=u+w2u,c2a=w2a,c2=Math.hypot(c2u,c2a),alpha2=Math.atan2(c2a,c2u)/rad;
 const lossNozzle=(1-a.phi*a.phi)*Hn,lossRotor=(1-a.psi*a.psi)*w2t*w2t/2000,lossExit=c2*c2/2000,work=u*(c1u-c2u)/1000,energyWork=H0-lossNozzle-lossRotor-lossExit;
 courseRequire(work>0,'Ступінь не дає додатної роботи. / Stage does not produce positive work.');
 const outlet=calculate('ph',a.pOut,ideal.h+lossNozzle+lossRotor,model).state;
 const metrics={H0,Hn,Hr,cf,u,c1t,c1,w1,beta1,beta2,w2t,w2,c2,alpha2,lossNozzle,lossRotor,lossExit,work,efficiency:work/H0,recoveredEfficiency:work/(H0-a.recovery*lossExit),power:a.flow*work,diameter:u/(Math.PI*a.frequency),balanceResidual:work-energyWork};
 const specifications=[['H0','Наявний теплоперепад','Available heat drop','H₀ = h₀ + c₀²/2000 − h₂s',`${courseNumber(inlet.h)} + ${a.c0}²/2000 − ${courseNumber(ideal.h)}`,'kJ/kg'],['Hn','Перепад у соплах','Nozzle heat drop','Hс = (1−ρ)H₀',`(1 − ${a.reaction}) × ${courseNumber(H0)}`,'kJ/kg'],['Hr','Перепад у роторі','Rotor heat drop','Hр = ρH₀',`${a.reaction} × ${courseNumber(H0)}`,'kJ/kg'],['cf','Фіктивна швидкість','Fictitious velocity','cф = √(2000H₀)',`√(2000 × ${courseNumber(H0)})`,'m/s'],['u','Колова швидкість','Blade speed','u = (u/cф)cф',`${a.speedRatio} × ${courseNumber(cf)}`,'m/s'],['c1','Швидкість після сопел','Nozzle exit velocity','c₁ = φ√(2000Hс)',`${a.phi} × √(2000 × ${courseNumber(Hn)})`,'m/s'],['w1','Відносна швидкість на вході','Relative inlet velocity','w₁ = √[(c₁cosα₁−u)²+(c₁sinα₁)²]',`√[(${courseNumber(c1u)} − ${courseNumber(u)})² + ${courseNumber(c1a)}²]`,'m/s'],['beta1','Кут входу ротора','Rotor inlet angle','β₁ = atan2(c₁sinα₁,c₁cosα₁−u)',`atan2(${courseNumber(c1a)}, ${courseNumber(w1u)})`,'°'],['beta2','Кут виходу ротора','Rotor exit angle','β₂ = β₁−Δβ',`${courseNumber(beta1)} − ${a.betaOffset}`,'°'],['w2','Відносна швидкість на виході','Relative exit velocity','w₂ = ψ√(w₁²+2000Hр)',`${a.psi} × √(${courseNumber(w1)}² + 2000 × ${courseNumber(Hr)})`,'m/s'],['alpha2','Кут абсолютного виходу','Absolute exit angle','α₂ = atan2(c₂a,c₂u)',`atan2(${courseNumber(c2a)}, ${courseNumber(c2u)})`,'°'],['c2','Абсолютна вихідна швидкість','Absolute exit velocity','c₂ = √[(u−w₂cosβ₂)²+(w₂sinβ₂)²]',`√(${courseNumber(c2u)}² + ${courseNumber(c2a)}²)`,'m/s'],['lossNozzle','Втрати в соплах','Nozzle loss','Δhс = (1−φ²)Hс',`(1 − ${a.phi}²) × ${courseNumber(Hn)}`,'kJ/kg'],['lossRotor','Втрати в роторі','Rotor loss','Δhр = (1−ψ²)w₂t²/2000',`(1 − ${a.psi}²) × ${courseNumber(w2t)}²/2000`,'kJ/kg'],['lossExit','Вихідна кінетична енергія','Exit kinetic energy','Δhв = c₂²/2000',`${courseNumber(c2)}²/2000`,'kJ/kg'],['work','Лопаткова робота (Ейлер)','Blade work (Euler)','wл = u(c₁u−c₂u)/1000',`${courseNumber(u)} × (${courseNumber(c1u)} − ${courseNumber(c2u)})/1000`,'kJ/kg'],['efficiency','ККД без використання вихідної енергії','Efficiency without exit recovery','ηл = wл/H₀',`${courseNumber(work)} / ${courseNumber(H0)}`,'–'],['recoveredEfficiency','ККД з заданим χ','Efficiency with specified χ','ηол = wл/(H₀−χΔhв)',`${courseNumber(work)} / (${courseNumber(H0)} − ${a.recovery} × ${courseNumber(lossExit)})`,'–'],['power','Лопаткова потужність','Blade power','Nл = ṁwл',`${a.flow} × ${courseNumber(work)}`,'kW'],['diameter','Середній діаметр ступеня','Mean stage diameter','D = u/(πn)',`${courseNumber(u)} / (π × ${a.frequency})`,'m'],['balanceResidual','Перевірка Ейлера та втрат','Euler/loss balance check','ε = wл−(H₀−Δhс−Δhр−Δhв)',`${courseNumber(work)} − ${courseNumber(energyWork)}`,'kJ/kg']];
 return {input:a,model,metrics,states:[{...inlet,name:'0'},{...ideal,name:'2s'},{...outlet,name:'2'}],steps:specifications.map(([k,uk,en,f,s,unit])=>courseStep(k,uk,en,f,s,metrics[k],unit)),vectors:{c1:[c1u,c1a],w1:[w1u,w1a],c2:[c2u,c2a],w2:[w2u,w2a],u},warnings:[],notes:[courseNote('Кути відлічуються від колової осі. Середня лінія потоку; задані φ, ψ та реактивність; інші втрати не враховані.','Angles are measured from the tangential axis. Meanline flow with specified φ, ψ and reaction; other losses are excluded.'),courseNote('χ — незалежне припущення про наступний ступінь. Відновлена вихідна енергія не додається до потужності цього ступеня.','χ is an independent assumption about the following stage. Recovered exit energy is not added to this stage’s power.'),courseNote('На h–s показано вхід, ідеальний і дійсний вихід. Проміжний тиск сопел не заданий, тому окремі стани сопел не вигадуються.','The h–s plot shows inlet, ideal and actual outlet. Nozzle intermediate pressure is unspecified; nozzle states are not inferred.')]};
}
function courseCladLambda(t){return 4e-8*t*t*t-5e-5*t*t+.0243*t+16.129;}
function courseCladRise(outer,target,a){
 if(a.cladMethod==='constant')return target/a.cladConductivity;
 const residual=d=>courseCladLambda(outer+d/2)*d-target;
 let lo=0,hi=1;while(residual(hi)<0&&hi<2000)hi*=2;
 courseRequire(residual(hi)>=0,'Не вдалося знайти перепад у оболонці. / Could not solve cladding temperature rise.');
 for(let i=0;i<65;i++){const mid=(lo+hi)/2;if(residual(mid)<0)lo=mid;else hi=mid;}return (lo+hi)/2;
}
