 courseRequire(df>hole&&hole>=0,'Паливо й оболонка мають перетин або від’ємний діаметр. / Invalid fuel/cladding diameters.');
 const flats=Math.ceil((Math.sqrt(3)*pitch*(a.layers-1)+d+2*a.ductThickness/1000)*1000)/1000,innerFlats=flats-2*a.ductThickness/1000,cellArea=Math.sqrt(3)/2*(flats+a.bundleGap/1000)**2,ductArea=Math.sqrt(3)/2*(flats*flats-innerFlats*innerFlats),solidArea=Math.PI/4*(a.rods*d*d+a.guides*(a.guideDiameter/1000)**2);
