 const dh=outState.h-inState.h;courseRequire(dh>0,'Ентальпія на виході має бути вищою. / Outlet enthalpy must be higher.');
 const flow=a.thermalMW*1000/dh,volume=a.thermalMW/a.volumeHeat,diameter=Math.cbrt(4*volume/(Math.PI*a.heightRatio)),height=diameter*a.heightRatio,bundles=Math.ceil(Math.PI*diameter*diameter/4/cellArea),beta=Math.PI/(height+2*a.reflector),sinHalf=Math.sin(beta*height/2),axialPeak=beta*height/(2*sinHalf),peakLinear=a.thermalMW*1e6*a.fuelFraction*a.radialPeak*beta/(2*bundles*a.rods*sinHalf);
