  const s=calculate('ph',p,h,model).state,t=s.T-273.15,velocity=flow*s.v/(bundles*waterArea),Re=velocity*hydraulicDiameter/(s.mu*s.v),Pr=s.cp*1000*s.mu/s.lambda,coefficient=.026*a.pitchRatio-.006,alpha=coefficient*s.lambda/hydraulicDiameter*Math.pow(Re,.8)*Math.cbrt(Pr),qLinear=peakLinear*Math.cos(beta*z);
