  const cladOuter=t+qLinear*a.heatFactor/(Math.PI*d*alpha),target=qLinear*a.conductionFactor*Math.log(d/di)/(2*Math.PI),cladRise=courseCladRise(cladOuter,target,a),cladInner=cladOuter+cladRise,gapRise=qLinear*a.conductionFactor*Math.log(di/df)/(2*Math.PI*a.gapConductivity),fuelSurface=cladInner+gapRise,gasMeanK=cladInner+gapRise/2+273.15,gasP=a.gasPressure*gasMeanK/a.gasInitialK;
