 const tables=[{headers:english?['Quantity','Formula','Substitution','Result','Unit']:['Величина','Формула','Підстановка','Результат','Одиниця'],rows:q.steps.map(s=>[s.label[english?1:0],s.formula,s.substitution,s.value,s.unit])}];
 if(q.profile){const index=Math.floor(q.profile.length/2);tables.push({headers:tables[0].headers,rows:courseworkNodeSteps(q,index).map(s=>[(english?'Node':'Точка')+' z='+courseNumber(q.profile[index].z)+' m: '+s.label[english?1:0],s.formula,s.substitution,s.value,s.unit])});}
 if(q.profile)tables.push({headers:['z [m]','p [MPa abs]','q′ [kW/m]','h [kJ/kg]','t [°C]','v [m³/kg]','w [m/s]','μ [Pa s]','λ [W/(m K)]','Pr','Re','α [W/(m² K)]','t sat [°C]','t clad out [°C]','t clad in [°C]','t fuel surface [°C]','p gas [MPa]'],rows:q.profile.map(r=>['z','p','qLinear','h','t','v','velocity','mu','lambda','Pr','Re','alpha','saturationC','cladOuter','cladInner','fuelSurface','gasP'].map(k=>r[k]))});
