 const points=specs.flatMap(s=>s[2]),xmin=Math.min(...points.map(p=>p[0])),xmax=Math.max(...points.map(p=>p[0])),ymin=Math.min(...points.map(p=>p[1])),ymax=Math.max(...points.map(p=>p[1])),dx=xmax-xmin||1,dy=ymax-ymin||1,X=x=>85+630*(x-xmin)/dx,Y=y=>300-245*(y-ymin)/dy;
 const ticks=Array.from({length:5},(_,i)=>{const f=i/4;return `<text x="${85+630*f}" y="322" text-anchor="middle">${Number((xmin+dx*f).toPrecision(4))}</text><text x="78" y="${305-245*f}" text-anchor="end">${Number((ymin+dy*f).toPrecision(4))}</text>`;}).join('');
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 430" role="img" aria-label="${english?'Calculation chart':'Графік розрахунку'}"><g font-family="Arial" font-size="13" fill="#18364e"><path d="M85 45V300H730" fill="none" stroke="#777"/>${ticks}<text x="410" y="346" text-anchor="middle">${xLabel}</text><text x="85" y="24">${yLabel}</text>${specs.map(([color,label,pts],i)=>`<polyline points="${pts.map(([x,y])=>X(x)+','+Y(y)).join(' ')}" fill="none" stroke="${color}" stroke-width="2"/>${pts.map(([x,y])=>`<circle cx="${X(x)}" cy="${Y(y)}" r="2" fill="${color}"/>`).join('')}<text x="${85+(i%3)*230}" y="${370+Math.floor(i/3)*25}" fill="${color}">${label}</text>`).join('')}</g></svg>`;
