const reportEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function boundedText(v,max){if(typeof v!=='string'||v.length>max)throw Error('Некоректний текст навчального звіту.');return v;}
const canonicalStateModes=['pt','ph','ps','satp','satt','px','tx','hs','th','ts','prho','trho','pv','tv','pu','tu','us','vs','hv','uv'];
function readStudyReport(value){
 if(value==null)return {author:'',assignment:'',intro:'',entries:[]};
 if(!value||typeof value!=='object'||!Array.isArray(value.entries)||value.entries.length>20||JSON.stringify(value).length>1000000)throw Error('Звіт: максимум 20 блоків і 1 МБ.');
 const out={author:boundedText(value.author??'',120),assignment:boundedText(value.assignment??'',200),intro:boundedText(value.intro??'',3000),entries:[]};
 for(const e of value.entries){
  if(!e||!['cycle-comparison','custom-cycle','water-process','comparison','state','process','flow','npp','diagram','cycle','exchanger','research','laboratory','coursework'].includes(e.kind)||!(['water-process','custom-cycle','cycle-comparison'].includes(e.kind)?PROCESS_MODELS:['IF97','IAPWS-95']).includes(e.model||'IF97'))throw Error('Некоректний блок звіту.');
  const entry={kind:e.kind,model:e.model||'IF97',title:boundedText(e.title??'',120),comment:boundedText(e.comment??'',3000)};
  if(e.kind==='diagram'){
   const image=boundedText(e.image,300000);if(!/^data:image\/png;base64,[A-Za-z0-9+/]+={0,2}$/.test(image))throw Error('Діаграма має бути PNG.');
   const bytes=atob(image.slice(22));if(bytes.length<24||!bytes.startsWith('\x89PNG\r\n\x1a\n')||bytes.slice(12,16)!=='IHDR')throw Error('Некоректний PNG.');
   const size=offset=>Array.from(bytes.slice(offset,offset+4)).reduce((n,c)=>n*256+c.charCodeAt(0),0);if(size(16)<=0||size(20)<=0||size(16)>5000||size(20)>5000)throw Error('Завелика діаграма.');
   entry.image=image;entry.caption=boundedText(e.caption??'',2000);
  }else{
   if(!e.input||typeof e.input!=='object'||Array.isArray(e.input))throw Error('Немає входів блоку звіту.');
   entry.input=e.kind==='cycle-comparison'?readCycleComparisonInput(e.input):e.kind==='custom-cycle'?readCustomCycleInput(e.input):e.kind==='water-process'?readWaterProcessInput(e.input):e.kind==='comparison'?readStateComparison(e.input):e.kind==='coursework'?courseworkInput(e.input):e.kind==='laboratory'?readLabInput(e.input):JSON.parse(JSON.stringify(e.input));
   if(e.kind==='state'&&(!canonicalStateModes.includes(entry.input.mode)||!Number.isFinite(entry.input.a)||!Number.isFinite(entry.input.b)))throw Error('Некоректний стан звіту.');
   if(e.kind==='process'&&(!['turbine','flash','throttle','pump','compressor','heat-exchanger'].includes(entry.input.type)||!Array.isArray(entry.input.args)||!entry.input.args.every(Number.isFinite)))throw Error('Некоректний процес звіту.');
   if(e.kind==='flow'&&entry.input.fluidModel!=null)boundedText(entry.input.fluidModel,120);
   evaluateReportEntry(entry); // Imported results and arbitrary HTML are never accepted.
  }
  if(e.kind==='custom-cycle'&&e.view!=null)entry.view=readCycleChartView(e.view);
  if(e.origin&&e.kind==='flow')entry.origin=readWorkspace({active:'flow',panels:{flow:e.origin}}).panels.flow;
  out.entries.push(entry);
 }
 return out;
}
